INSERT INTO knowledge_private.tests (id, owner_id, title, description, category, pass_mark, questions, published, demo) VALUES ('demo-information', NULL, 'Работа с информацией', 'Проверьте внимательность на примере шести рабочих ситуаций. Все условия даны в вопросах.', 'Демонстрация', 80, '[{"id":"d1","text":"В учебной компании актуальные инструкции хранятся в базе знаний. В чате вы нашли другую версию инструкции. На какой документ нужно ориентироваться?","options":["На последний пересланный файл в чате","На актуальную инструкцию в базе знаний","На документ с самым коротким текстом","На любой из двух документов"],"correct":1,"explanation":"По условию вопроса именно база знаний содержит актуальные инструкции."},{"id":"d2","text":"По правилам учебной компании заявка считается завершённой после подтверждения заказчика. Работа выполнена, но подтверждения ещё нет. Каков статус заявки?","options":["Завершена","Отменена","Ожидает подтверждения","Не требует дальнейших действий"],"correct":2,"explanation":"Выполнение работы и подтверждение заказчика — два отдельных условия завершения заявки."},{"id":"d3","text":"В отчёте за понедельник указано 12 заявок, за вторник — 8. Сколько заявок поступило за два дня?","options":["16","18","20","24"],"correct":2,"explanation":"12 + 8 = 20 заявок."},{"id":"d4","text":"В инструкции сказано: «Перед отправкой проверьте адрес получателя и вложение». Что необходимо проверить?","options":["Только имя файла","Только адрес получателя","Только текст письма","Адрес получателя и вложение"],"correct":3,"explanation":"В инструкции явно указаны обе проверки."},{"id":"d5","text":"В учебной компании задачи обрабатывают по возрастанию номера приоритета: сначала 1, затем 2, затем 3. Какую задачу следует взять первой?","options":["Задачу с приоритетом 1","Задачу с приоритетом 2","Задачу с приоритетом 3","Любую задачу"],"correct":0,"explanation":"Чем меньше номер приоритета в этом примере, тем раньше выполняют задачу."},{"id":"d6","text":"Для доступа к документу по условию требуется согласование руководителя. Коллега прислал ссылку, но согласования пока нет. Какой следующий шаг соответствует условию?","options":["Считать ссылку согласованием","Получить согласование руководителя","Передать ссылку другим коллегам","Пропустить согласование"],"correct":1,"explanation":"Получение ссылки не заменяет требуемое согласование."}]'::jsonb, true, true);
